<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { apiClient } from '@/services/api'; import type { Employee } from '@/types'
const router = useRouter(); const items = ref<Employee[]>([]); const total = ref(0); const page = ref(1); const limit = 10; const loading = ref(false); const error = ref(''); const success = ref('')
async function load() { loading.value=true; error.value=''; try { const r=await apiClient.listEmployees((page.value-1)*limit,limit); items.value=r.items; total.value=r.total } catch(e) { error.value=apiClient.getErrorMessage(e) } finally { loading.value=false } }
async function deactivate(row: Employee) { if (!confirm(`Deactivate ${row.full_name}?`)) return; try { await apiClient.deactivateEmployee(row.id); success.value='Employee deactivated.'; await load() } catch(e) { error.value=apiClient.getErrorMessage(e) } }
onMounted(load)
</script>
<template><main class="space-y-6"><div class="flex items-center justify-between"><h1 class="text-2xl font-bold">Employees</h1><button class="rounded bg-indigo-600 px-4 py-2 text-white" @click="router.push('/employees/new')">Add employee</button></div><div v-if="error" class="rounded bg-red-50 p-3 text-red-700">{{ error }}</div><div v-if="success" class="rounded bg-green-50 p-3 text-green-700">{{ success }}</div><div class="overflow-x-auto rounded-lg bg-white shadow"><table class="min-w-full text-left text-sm"><thead><tr class="border-b bg-slate-50"><th class="p-3">Code</th><th class="p-3">Name</th><th class="p-3">Email</th><th class="p-3">Department</th><th class="p-3">Status</th><th class="p-3">Actions</th></tr></thead><tbody><tr v-for="row in items" :key="row.id" class="border-b"><td class="p-3">{{ row.employee_code }}</td><td class="p-3">{{ row.full_name }}</td><td class="p-3">{{ row.email }}</td><td class="p-3">{{ row.department || '—' }}</td><td class="p-3">{{ row.is_active ? 'Active' : 'Inactive' }}</td><td class="flex gap-2 p-3"><button class="text-indigo-600" @click="router.push(`/employees/${row.id}/edit`)">Edit</button><button v-if="row.is_active" class="text-red-600" @click="deactivate(row)">Deactivate</button></td></tr></tbody></table></div><div class="flex items-center justify-between"><span class="text-sm text-slate-500">{{ total }} employees</span><div class="flex gap-2"><button class="rounded border px-3 py-1 disabled:opacity-50" :disabled="page === 1 || loading" @click="page--; load()">Previous</button><button class="rounded border px-3 py-1 disabled:opacity-50" :disabled="page * limit >= total || loading" @click="page++; load()">Next</button></div></div></main></template>
